// Changes: Select an IR instruction for a checked binary operator.
static IrInstructionType binary_instruction(Ctx* ctx,
                                            AstNodeType kind,
                                            IrType result_type) {
  switch (kind) {
    case AST_NODE_ADD:
      // The source uses + for both numeric addition and string concatenation.
      return result_type == IR_STRING ? IR_INST_CONCAT : IR_INST_ADD;
    case AST_NODE_SUB:
      return IR_INST_SUB;
    case AST_NODE_MUL:
      return IR_INST_MUL;
    case AST_NODE_DIV:
      return result_type == IR_INT ? IR_INST_IDIV : IR_INST_DIV;
    case AST_NODE_EQ:
      return IR_INST_EQ;
    case AST_NODE_NEQ:
      return IR_INST_NE;
    case AST_NODE_LT:
      return IR_INST_LT;
    case AST_NODE_LE:
      return IR_INST_LE;
    case AST_NODE_GT:
      return IR_INST_GT;
    case AST_NODE_GE:
      return IR_INST_GE;
    default:
      THROW(E_INTERNAL_ERROR, "Unexpected binary expression kind: %d", kind);
      return IR_INST_ADD;  // Unreachable
  }
}

