// Changes: Load a variable from its semantic slot using the shared emitter.
static IrOperand lower_identifier(Ctx* ctx,
                                  IrFunctionId function_id,
                                  IrBlockId block_id,
                                  AstNode* node) {
  const SymtableData* symbol = ast_node_get_symbol(node);

  // Unit has one possible value, so reading a Unit variable needs no load.
  if (symbol->ir_type == IR_UNIT)
    return unit_operand();

  return emit_load(ctx, function_id, block_id, symbol->ir_index,
                   symbol->ir_type);
}

