// Changes: Emit a built-in call with one operand.
static IrOperand add_builtin(Ctx* ctx,
                             IrFunctionId function_id,
                             IrBlockId block_id,
                             IrFunctionType type,
                             IrType result_type,
                             IrOperand argument) {
  return add_call(ctx, function_id, block_id,
                  (IrInstruction){.type = IR_INST_CALL,
                                  .result_type = result_type,
                                  .operands.call = {.type = type,
                                                    .id = IR_INVALID_ID,
                                                    .args = &argument,
                                                    .arg_count = 1}});
}

