// Changes: Lower a primitive member on paths where its receiver continues.
static IrOperand lower_member(Ctx* ctx,
                              IrFunctionId function_id,
                              IrBlockId* block_id,
                              AstNode* node) {
  AstNode* receiver_node = ast_node_child(ctx, node, AST_MEMBER_RECEIVER);
  IrOperand receiver =
      lower_expression(ctx, function_id, block_id, receiver_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  // Floor is an IR instruction. Other members are calls on the receiver.
  if (strcmp(ast_node_get_name(node), "floor") == 0)
    return add_unary(ctx, function_id, *block_id, IR_INST_FLOOR, IR_DOUBLE,
                     receiver);

  const SymtableData* symbol = ast_node_get_symbol(node);
  return add_builtin(ctx, function_id, *block_id,
                     (IrFunctionType)symbol->ir_index, symbol->ir_type,
                     receiver);
}

